def __eq__(self, other: Any):
    """Test equality of CSM instances."""
    if not isinstance(other, self.__class__):
        return False

    graph_0 = self.graph
    graph_1 = other.graph

    if self.name != other.name:
        return False

    if self.reference_time != other.reference_time:
        return False

    if len(graph_0.nodes) != len(graph_1.nodes):
        return False

    if not util.compare_nested(
        {sub.name: sub for sub in self.subsystem_info},
        {sub.name: sub for sub in other.subsystem_info},
    ):
        return False

    # check nodes
    for node in graph_0.nodes:
        if node not in graph_1.nodes:
            return False

    # check edges
    for edge in graph_0.edges:
        if edge not in graph_1.edges:
            return False

    # check coordinate systems
    for edge in graph_0.edges:
        lcs_0 = self.graph.edges[(edge[0], edge[1])]["transformation"]
        lcs_1 = other.graph.edges[(edge[0], edge[1])]["transformation"]
        if lcs_0 != lcs_1:
            return False

    # check attached data
    data_names_0 = set(self.data_names)
    data_names_1 = set(other.data_names)

    # data names must be identical
    if data_names_0 != data_names_1:
        return False

    # check data values for each data name
    for data_name in data_names_0:
        try:
            _, data_0 = self._find_data(data_name)
            _, data_1 = other._find_data(data_name)

            # handle different data types
            if hasattr(data_0, 'equals'):
                # xarray DataArray or similar with equals method
                if not data_0.equals(data_1):
                    return False
            elif hasattr(data_0, '__array__') or hasattr(data_0, '__eq__'):
                # numpy array or similar
                if not np.array_equal(data_0, data_1):
                    return False
            else:
                # fallback to regular equality
                if data_0 != data_1:
                    return False
        except (KeyError, AttributeError):
            # if we can't find or compare the data, they're not equal
            return False

    return True

