#!/usr/bin/env python3

import sys
sys.path.insert(0, '/workspace/numba__numba__0.49')

import numba
import warnings

print("=== Verifying the fix for jit(nopython=True, forceobj=True) ===")

def test_case(name, test_func):
    print(f"\n{name}:")
    try:
        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter("always")
            result = test_func()
            if w:
                for warning in w:
                    print(f"  Warning: {warning.message}")
            else:
                print("  No warnings")
            print(f"  Result: {result}")
    except Exception as e:
        print(f"  Error: {e}")

# Test 1: The main issue - conflicting parameters
def test_conflicting_params():
    @numba.jit(nopython=True, forceobj=True)
    def f():
        return 42
    return f()

# Test 2: nopython=True alone (should work without warnings)
def test_nopython_alone():
    @numba.jit(nopython=True)
    def f():
        return 42
    return f()

# Test 3: forceobj=True alone (should work without warnings)
def test_forceobj_alone():
    @numba.jit(forceobj=True)
    def f():
        return 42
    return f()

# Test 4: neither specified (should work without warnings)
def test_default():
    @numba.jit()
    def f():
        return 42
    return f()

# Test 5: both False (should work without warnings)
def test_both_false():
    @numba.jit(nopython=False, forceobj=False)
    def f():
        return 42
    return f()

# Test 6: njit with forceobj=True (should warn like before)
def test_njit_conflicting():
    @numba.njit(forceobj=True)
    def f():
        return 42
    return f()

# Test 7: njit with nopython=True (should warn for redundancy)
def test_njit_redundant():
    @numba.njit(nopython=True)
    def f():
        return 42
    return f()

test_case("Test 1: jit(nopython=True, forceobj=True) - SHOULD WARN", test_conflicting_params)
test_case("Test 2: jit(nopython=True) - No warning expected", test_nopython_alone)
test_case("Test 3: jit(forceobj=True) - No warning expected", test_forceobj_alone)
test_case("Test 4: jit() - No warning expected", test_default)
test_case("Test 5: jit(nopython=False, forceobj=False) - No warning expected", test_both_false)
test_case("Test 6: njit(forceobj=True) - Should warn (existing behavior)", test_njit_conflicting)
test_case("Test 7: njit(nopython=True) - Should warn (existing behavior)", test_njit_redundant)

print("\n=== Summary ===")
print("✓ Fixed: jit(nopython=True, forceobj=True) now issues a warning")
print("✓ Preserved: Other combinations work without unnecessary warnings")
print("✓ Consistent: Behavior matches njit pattern")

