def _get_loop_variables(self, node: Union[AnyLoop, AnyComprehension]) -> Set[str]:
    """Get variable names defined by the loop/comprehension."""
    variables = set()

    if hasattr(node, 'generators'):  # Comprehension
        # For comprehensions, collect all target variables from generators
        for generator in node.generators:
            generator_vars = name_nodes.get_variables_from_node(generator.target)
            variables.update(generator_vars)
    elif hasattr(node, 'target'):  # Regular loop (for/while don't have target, but for does)
        # For regular loops, get the iteration variable
        if hasattr(node, 'iter'):  # For loops have iter
            loop_vars = name_nodes.get_variables_from_node(node.target)
            variables.update(loop_vars)

    return variables

def _lambda_captures_loop_variables(
    self,
    lambda_node: ast.Lambda,
    loop_node: Union[AnyLoop, AnyComprehension],
) -> bool:
    """
    Check if a lambda captures variables from the enclosing loop scope.

    Returns True if the lambda references any variables defined by the loop.
    """
    # Get variables referenced in lambda body
    lambda_var_refs = self._extract_variable_names(lambda_node.body)

    # Get variables defined by the loop
    loop_vars = self._get_loop_variables(loop_node)

    # Check if there's overlap (capture)
    return bool(lambda_var_refs.intersection(loop_vars))

