    self,
    node: Union[AnyLoop, AnyComprehension],
) -> None:
    container_names = self._containers.get(type(node), ())
    for container in container_names:
        body = getattr(node, container, [])
        if not isinstance(body, list):
            body = [body]

        for subnode in body:
            # Find all lambda nodes in this subnode
            for lambda_node in walk.get_subnodes_by_type(subnode, ast.Lambda):
                # Only raise violation if lambda actually captures loop variables
                if self._lambda_captures_loop_variables(lambda_node, node):
