    # 2. Check that OpenWeatherMap is used instead
    print("\n2. Checking for OpenWeatherMap usage...")
    openweather_refs = [
        'OPENWEATHER_API_KEY',
        'openweathermap.org',
        'OpenWeatherMap'
    ]

