            print("  ✓ MAPBOX_API_TOKEN correctly loaded")
        else:
            print("  ❌ MAPBOX_API_TOKEN not loaded correctly")

        if OPENWEATHER_API_KEY == 'fake_openweather':
            print("  ✓ OPENWEATHER_API_KEY correctly loaded")
        else:
            print("  ❌ OPENWEATHER_API_KEY not loaded correctly")
    except Exception as e:
        print(f"  ❌ Error checking environment variables: {e}")

