        if isinstance(solver_arg, dict) and solver_arg.get('category') == 'hybrid':
            raise ValueError("QPU client cannot find hybrid solvers")
        return MockQPUSolver()

class MockHybridClient:
    def __init__(self, **kwargs):
        self.kwargs = kwargs
        print(f"MockHybridClient created with kwargs: {kwargs}")

    def get_solver(self):
        return MockHybridSolver()

def mock_client_from_config_qpu(**kwargs):
    """Mock function that simulates QPU client being selected due to config."""
    client_type = kwargs.get('client')
    if client_type is None:
        # Simulate reading from config where client=qpu is set
        client_type = 'qpu'  # This is the problematic case

    if client_type == 'qpu':
        return MockQPUClient(**kwargs)
    elif client_type == 'hybrid':
